            { title = 'Alchemy 0–10', note = '• Tsurara (cap 6): Ice Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), 2 × Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Bag Of Cornstarch (cap 9): Lightning Crystal + 2 × Ear Of Millioncorn (Benaige, Southern San d\'Oria, 49 gil)\n• Antidote (cap 3): Water Crystal + Wijnruit (Dabih Jajalioh, Ru\'Lude Gardens, 120 gil), Bunch Of San Dorian Grapes (Aveline, Southern San d\'Oria, 79 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Flask Of Deodorizer (cap 10): Wind Crystal + Flask Of Olive Oil (Aveline, Southern San d\'Oria, 16 gil), Sprig Of Chamomile (Kopopo, Windurst Waters, 57 gil), Sprig Of Sage (Wahraga, Aht Urhgan Whitegate, 156 gil)' },
            { title = 'Alchemy 10–20', note = '• Vial Of Mercury (cap 16): Lightning Crystal + 4 × Cobalt Jellyfish (Mep Nhapopoluko, Bibiki Bay, 32 gil)\n• Pinch Of Poison Dust (cap 12): Lightning Crystal + 2 × Yellow Globe (Babubu, Port Windurst, 160 gil)\n• Flask Of Echo Drops (cap 20): Water Crystal + Sprig Of Sage (Wahraga, Aht Urhgan Whitegate, 156 gil), Pot Of Honey (Kopopo, Windurst Waters, 590 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Flask Of Poison Potion (cap 18): Water Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Pinch Of Poison Dust (Stinknix, Lower Jeuno, 320 gil)' },
            { title = 'Alchemy 20–30', note = '• Jar Of Yellow Textile Dye (cap 29): Water Crystal + Onz Of Turmeric (Jabbar, Port Bastok, 512 gil)\n• Sairui-ran (cap 28), also needs another craft at 11: Earth Crystal + Bunch Of Kazham Peppers (Ghemi Sinterilo, Kazham, 63 gil), Pinch Of Bomb Ash (Olaf, Metalworks, 540 gil), Sheet Of Bast Parchment (Vuliaie, Norg, 2095 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)\n• Pot Of Vermilion Lacquer (cap 24): Fire Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Pinch Of Sulfur (Wahraga, Aht Urhgan Whitegate, 826 gil)\n• Flask Of Blinding Potion (cap 28): Lightning Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Nebimonite (Babubu, Port Windurst, 1289 gil)' },
            { title = 'Alchemy 30–40', note = '• Jar Of Firesand (cap 40): Earth Crystal + 2 × Pinch Of Bomb Ash (Olaf, Metalworks, 540 gil), Pinch Of Sulfur (Wahraga, Aht Urhgan Whitegate, 826 gil)\n• Artificial Lens (cap 34): Fire Crystal + 2 × Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil)\n• Vial Of Plasma Oil (cap 39): Water Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), 2 × Chunk Of Flan Meat (Wahraga, Aht Urhgan Whitegate, 644 gil)\n• Orb Of Dark Fewell (cap 35): Dark Crystal + Vial Of Slime Oil (Maymunah, Bastok Mines, 4880 gil), Black Rock (Yabby Tanmikey, Mhaura, 4200 gil), Flasque Of Catalytic Oil (Nogga, Metalworks, 105 gil)' },
            { title = 'Alchemy 40–50', note = '• Loop Of Carbon Fiber (cap 45): Lightning Crystal + 4 × Pinch Of Bomb Ash (Olaf, Metalworks, 540 gil)\n• Phial Of Osseous Serum (cap 43), also needs another craft at 27: Water Crystal + 4 × Bone Chip (Shih Tayuun, Windurst Woods, 349 gil), Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil)\n• Pinch Of Prism Powder (cap 41): Light Crystal + 2 × Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil), Artificial Lens (Maymunah, Bastok Mines, 4563 gil)\n• Handful Of Fire Arrowheads (cap 44), also needs another craft at 23: Fire Crystal + Vial Of Slime Oil (Maymunah, Bastok Mines, 4880 gil), Iron Ingot (Ndego, Al Zahbi, 3060 gil), Square Of Grass Cloth (Kuzah Hpirohpon, Windurst Woods, 1344 gil)' },
            { title = 'Alchemy 50–60', note = '• Flask Of Holy Water (cap 51): Light Crystal + Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Ranka (cap 52): Earth Crystal + 2 × Queen Of The Night (Areebah, Upper Jeuno, 690 gil)\n• Bottle Of Hi-potion Drops (cap 60): Fire Crystal + 2 × Sprig Of Sage (Wahraga, Aht Urhgan Whitegate, 156 gil), Malboro Vine (Wahraga, Aht Urhgan Whitegate, 3000 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Hi-potion (cap 60): Water Crystal + 2 × Sprig Of Sage (Wahraga, Aht Urhgan Whitegate, 156 gil), Malboro Vine (Wahraga, Aht Urhgan Whitegate, 3000 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)' },
            { title = 'Alchemy 60–70', note = '• Pinch Of Venom Dust (cap 62): Lightning Crystal + 2 × Ogre Eel (Babubu, Port Windurst, 601 gil)\n• Square Of Ebonite (cap 63): Lightning Crystal + Pinch Of Sulfur (Wahraga, Aht Urhgan Whitegate, 826 gil), 2 × Chunk Of Flan Meat (Wahraga, Aht Urhgan Whitegate, 644 gil)\n• Flask Of Venom Potion (cap 68): Water Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Pinch Of Venom Dust (Stinknix, Lower Jeuno, 1035 gil)\n• Single Hook Fishing Rod (cap 69): Fire Crystal + 5 × Loop Of Carbon Fiber (Maymunah, Bastok Mines, 1080 gil), 2 × Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil)' },
            { title = 'Alchemy 70–80', note = '• Chunk Of High Ebonite (cap 73): Lightning Crystal + Pinch Of Sulfur (Wahraga, Aht Urhgan Whitegate, 826 gil), 3 × Chunk Of Flan Meat (Wahraga, Aht Urhgan Whitegate, 644 gil)\n• Flask Of Paralyze Potion (cap 78): Water Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Pinch Of Paralysis Dust (Stinknix, Lower Jeuno, 2000 gil)\n• Halcyon Rod (cap 76): Fire Crystal + Cermet Chunk (Maymunah, Bastok Mines, 19520 gil), 4 × Loop Of Carbon Fiber (Maymunah, Bastok Mines, 1080 gil), 2 × Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil)\n• Air Rider (cap 78), also needs another craft at 45: Fire Crystal + Piece Of Lauan Lumber (Dehbi Moshal, Al Zahbi, 97 gil), 2 × Jar Of Firesand (Maymunah, Bastok Mines, 21862 gil), Sheet Of Bast Parchment (Vuliaie, Norg, 2095 gil), Goblin Doll (Pawkrix, Lower Jeuno, 500 gil), Pinch Of Twinkle Powder (Upih Khachla, Windurst Waters, 400 gil)' },
            { title = 'Alchemy 80–90', note = '• Square Of Polyflan (cap 83): Lightning Crystal + Chunk Of Flan Meat (Wahraga, Aht Urhgan Whitegate, 644 gil), Vial Of Chimera Blood (Wahraga, Aht Urhgan Whitegate, 3000 gil)\n• Ouka Ranman (cap 84), also needs another craft at 23: Earth Crystal + Jar Of Firesand (Maymunah, Bastok Mines, 21862 gil), Amaryllis (Dabih Jajalioh, Ru\'Lude Gardens, 120 gil), 2 × Sheet Of Bast Parchment (Vuliaie, Norg, 2095 gil)\n• Composite Fishing Rod (cap 89): Fire Crystal + 2 × Cermet Chunk (Maymunah, Bastok Mines, 19520 gil), 3 × Loop Of Carbon Fiber (Maymunah, Bastok Mines, 1080 gil), 2 × Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil)\n• Espadon (cap 90): Fire Crystal + Square Of Coeurl Leather (Kueh Igunahmori, Southern San d\'Oria, 11333 gil), 3 × Cermet Chunk (Maymunah, Bastok Mines, 19520 gil)' },
            { title = 'Alchemy 90–100', note = '• Max-potion (cap 95): Water Crystal + Alchemy Kit 95\n• Ice Lance (cap 93): Ice Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Cermet Lance\n• Ice Shield (cap 97): Ice Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Diamond Shield\n• Bottle Of Antacid (cap 93), also needs another craft at 43: Earth Crystal + Pinch Of Dried Marjoram (Benaige, Southern San d\'Oria, 49 gil), Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), Sprig Of Chamomile (Kopopo, Windurst Waters, 57 gil), Pinch Of Dried Mugwort, Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)' },
            { title = 'Alchemy 100–110', note = '• Azure Cermet (cap 105): Fire Crystal + Cermet Chunk (Maymunah, Bastok Mines, 19520 gil), Flask Of Panacea, Azure Leaf\n• Vivi-valve Ii (cap 103): Fire Crystal + Mythril Sheet (Visala, Bastok Markets, 45600 gil), Loop Of Glass Fiber (Wahraga, Aht Urhgan Whitegate, 1992 gil), Light Bead, Vanir Battery\n• Jug Of Saline Broth (cap 104): Dark Crystal + Vial Of Mercury (Wahraga, Aht Urhgan Whitegate, 3375 gil), Vial Of Beastman Blood, Philosophers Stone, Vestige Of A Buried Trait\n• Hexed Nails (cap 105): Dark Crystal + Revival Tree Root, Ethereal Squama, Vial Of Belladonna Sap, Ebony Sabots (Chaupire, Northern San d\'Oria, 38707 gil)' }
    } },
    { name = 'Cooking', group = 'Crafting', desc = 'In each band, synthesize one of these until it stops giving skill, then move on. Cheapest first. Merchant prices are fixed; guild shop prices are the most they charge.', steps = {
            { title = 'Cooking 0–10', note = '• Peeled Crayfish (cap 3): Wind Crystal + Crayfish (Wahnid, Aht Urhgan Whitegate, 48 gil)\n• Ear Of Roasted Corn (cap 2): Fire Crystal + Ear Of Millioncorn (Benaige, Southern San d\'Oria, 49 gil)\n• Hard-boiled Egg (cap 6): Fire Crystal + Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)\n• Boiled Crayfish (cap 9): Fire Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Crayfish (Wahnid, Aht Urhgan Whitegate, 48 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)' },
            { title = 'Cooking 10–20', note = '• Slice Of Sardine (cap 11): Wind Crystal + Hamsi (Wahnid, Aht Urhgan Whitegate, 21 gil)\n• Stick Of Selbina Butter (cap 20): Ice Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil)\n• Tortilla (cap 14): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Ear Of Millioncorn (Benaige, Southern San d\'Oria, 49 gil), Flask Of Olive Oil (Aveline, Southern San d\'Oria, 16 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil)\n• Bottle Of Apple Juice (cap 20): Water Crystal + 4 × Faerie Apple (Aveline, Southern San d\'Oria, 45 gil)' },
            { title = 'Cooking 20–30', note = '• Ball Of Insect Paste (cap 29): Earth Crystal + Ear Of Millioncorn (Benaige, Southern San d\'Oria, 49 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Little Worm (Gelzerio, Bastok Mines, 4 gil)\n• Jug Of Soy Milk (cap 21): Fire Crystal + 2 × Pod Of Blue Peas (Kopopo, Windurst Waters, 42 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Bottle Of Pineapple Juice (cap 30): Water Crystal + 2 × Kazham Pineapple (Ghemi Sinterilo, Kazham, 63 gil)\n• Strip Of Meat Jerky (cap 26): Ice Crystal + Pinch Of Dried Marjoram (Benaige, Southern San d\'Oria, 49 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Slice Of Giant Sheep Meat (Kopopo, Windurst Waters, 230 gil)' },
            { title = 'Cooking 30–40', note = '• Loaf Of Black Bread (cap 34): Fire Crystal + Bag Of Rye Flour (Dohdjuma, Selbina, 41 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Ball Of Sardine Paste (cap 31): Earth Crystal + Bag Of Horo Flour (Pawkrix, Lower Jeuno, 40 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Hamsi (Wahnid, Aht Urhgan Whitegate, 21 gil)\n• Jug Of Fish Broth (cap 37): Water Crystal + 4 × Hamsi (Wahnid, Aht Urhgan Whitegate, 21 gil)\n• Loaf Of Iron Bread (cap 34): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)' },
            { title = 'Cooking 40–50', note = '• Bottle Of Tomato Juice (cap 43): Water Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), 3 × Mithran Tomato (Ghemi Sinterilo, Kazham, 42 gil)\n• Piece Of Pie Dough (cap 42): Water Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil)\n• Bottle Of Grape Juice (cap 50): Dark Crystal + 4 × Bunch Of San Dorian Grapes (Aveline, Southern San d\'Oria, 79 gil)\n• Sugar Rusk (cap 45): Fire Crystal + Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), Loaf Of Iron Bread (Glyke, Upper Jeuno, 100 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)' },
            { title = 'Cooking 50–60', note = '• Ball Of Crayfish Paste (cap 52): Earth Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), 3 × Crayfish (Wahnid, Aht Urhgan Whitegate, 48 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Serving Of Batagreen Saute (cap 52): Fire Crystal + Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Clump Of Batagreens (Kopopo, Windurst Waters, 124 gil)\n• Bretzel (cap 53): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)\n• Bowl Of Egg Soup (cap 57): Fire Crystal + Pinch Of Black Pepper (Amalasanda, Lower Jeuno, 267 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)' },
            { title = 'Cooking 60–70', note = '• Block Of Stone Cheese (cap 61): Dark Crystal + Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil)\n• Colored Egg (cap 68): Fire Crystal + La Theine Cabbage (Aveline, Southern San d\'Oria, 24 gil), San Dorian Carrot (Aveline, Southern San d\'Oria, 33 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)\n• Blackened Frog (cap 64): Fire Crystal + Pinch Of Dried Marjoram (Benaige, Southern San d\'Oria, 49 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Copper Frog (Mendoline, Selbina, 248 gil)\n• Piece Of Raisin Bread (cap 67): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Bunch Of San Dorian Grapes (Aveline, Southern San d\'Oria, 79 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)' },
            { title = 'Cooking 70–80', note = '• Orange Kuchen (cap 80): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), 2 × Saruta Orange (Aveline, Southern San d\'Oria, 33 gil), Bird Egg (Denvihr, Port Bastok, 58 gil)\n• Serving Of Salmon Meuniere (cap 73): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pinch Of Black Pepper (Amalasanda, Lower Jeuno, 267 gil), Flask Of Olive Oil (Aveline, Southern San d\'Oria, 16 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Cheval Salmon (Mendoline, Selbina, 214 gil)\n• Cup Of Chocomilk (cap 79): Fire Crystal + Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), 4 × Kukuru Bean (Ghemi Sinterilo, Kazham, 126 gil), Pot Of Honey (Kopopo, Windurst Waters, 590 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Serving Of Green Curry (cap 76): Fire Crystal + Pod Of Blue Peas (Kopopo, Windurst Waters, 42 gil), Handful Of Bay Leaves (Aveline, Southern San d\'Oria, 135 gil), Onz Of Curry Powder (Amalasanda, Lower Jeuno, 1039 gil), Sprig Of Holy Basil (Jabbar, Port Bastok, 700 gil), Crayfish (Wahnid, Aht Urhgan Whitegate, 48 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Clump Of Beaugreens (Kopopo, Windurst Waters, 460 gil)' },
            { title = 'Cooking 80–90', note = '• Coconut Rusk (cap 85): Fire Crystal + Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Loaf Of Iron Bread (Glyke, Upper Jeuno, 100 gil), Bird Egg (Denvihr, Port Bastok, 58 gil), Elshimo Coconut (Ghemi Sinterilo, Kazham, 180 gil)\n• Cup Of Chamomile Tea (cap 83): Fire Crystal + 2 × Sprig Of Chamomile (Kopopo, Windurst Waters, 57 gil), Pot Of Honey (Kopopo, Windurst Waters, 590 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Serving Of Bass Meuniere (cap 83): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pinch Of Black Pepper (Amalasanda, Lower Jeuno, 267 gil), Flask Of Olive Oil (Aveline, Southern San d\'Oria, 16 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Saruta Orange (Aveline, Southern San d\'Oria, 33 gil), Dark Bass (Wahnid, Aht Urhgan Whitegate, 272 gil)\n• Flask Of Pamama Au Lait (cap 81): Water Crystal + Pot Of Honey (Kopopo, Windurst Waters, 590 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil), 2 × Bunch Of Pamamas (Ghemi Sinterilo, Kazham, 84 gil)' },
            { title = 'Cooking 90–100', note = '• Plate Of Urchin Sushi (cap 93): Earth Crystal + Box Of Tarutaru Rice (Kopopo, Windurst Waters, 276 gil), Clump Of Pamtam Kelp (Mep Nhapopoluko, Bibiki Bay, 39 gil), Bottle Of Rice Vinegar (Amalasanda, Lower Jeuno, 210 gil), Bibiki Urchin (Mep Nhapopoluko, Bibiki Bay, 3375 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil)\n• Serving Of Flounder Meuniere (cap 93): Fire Crystal + Bag Of San Dorian Flour (Benaige, Southern San d\'Oria, 62 gil), Stick Of Selbina Butter (Kopopo, Windurst Waters, 119 gil), Pinch Of Black Pepper (Amalasanda, Lower Jeuno, 267 gil), Flask Of Olive Oil (Aveline, Southern San d\'Oria, 16 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil), Black Sole (Babubu, Port Windurst, 6720 gil)\n• Plate Of Dorado Sushi (cap 93): Earth Crystal + Box Of Tarutaru Rice (Kopopo, Windurst Waters, 276 gil), Bottle Of Rice Vinegar (Amalasanda, Lower Jeuno, 210 gil), Noble Lady (Babubu, Port Windurst, 5572 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Jar Of Ground Wasabi (Amalasanda, Lower Jeuno, 2724 gil)\n• Dragon Steak (cap 95): Fire Crystal + Cooking Kit 95' },
            { title = 'Cooking 100–110', note = '• Flask Of Dragon Fruit Au Lait (cap 105): Water Crystal + Pot Of Honey (Kopopo, Windurst Waters, 590 gil), Jug Of Selbina Milk (Dohdjuma, Selbina, 62 gil), 2 × Dragon Fruit\n• Bowl Of Soy Sauce-based Ramen Soup (cap 104): Fire Crystal + 2 × Chicken Bone (Shih Tayuun, Windurst Woods, 163 gil), Wild Onion (Kopopo, Windurst Waters, 1934 gil), Slice Of Cockatrice Meat (Kopopo, Windurst Waters, 3968 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Sprig Of Cibol (Benaige, Southern San d\'Oria, 228 gil), Bottle Of Soy Sauce\n• Cup Of Date Tea (cap 105): Fire Crystal + Pot Of Maple Sugar (Benaige, Southern San d\'Oria, 41 gil), Clump Of Imperial Tea Leaves, Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Date\n• Himesama Rice Ball (cap 107): Fire Crystal + Box Of Tarutaru Rice (Kopopo, Windurst Waters, 276 gil), Clump Of Pamtam Kelp (Mep Nhapopoluko, Bibiki Bay, 39 gil), Chunk Of Rock Salt (Benaige, Southern San d\'Oria, 16 gil), Flask Of Distilled Water (Griselda, Bastok Mines, 12 gil), Slice Of Buffalo Meat, Burdock Root' }
    } },
    { name = 'Fishing', group = 'Crafting', desc = 'In each band, fish for one of these: where they bite and the bait they take. Skill rises fastest on fish a little above your skill.', steps = {
            { title = 'Fishing 0–10', note = '• Crayfish (skill 7) in Phanauet Channel, Carpenters Landing, Oldton Movalpolos, on Slice of Moat Carp (Wahnid, Aht Urhgan Whitegate, 254 gil)\n• Bastore Sardine (skill 9) in Manaclipper, Bibiki Bay, Valkurm Dunes, on Sabiki Rig (Babubu, Port Windurst, 2394 gil)\n• Cobalt Jellyfish (skill 5) in Manaclipper, Bibiki Bay, Lufaise Meadows, on Fly Lure (Babubu, Port Windurst, 540 gil)\n• Hamsi (skill 9) in Aht Urhgan Whitegate, Silver Sea route to Nashmau, Silver Sea route to Al Zahbi, on Sabiki Rig (Babubu, Port Windurst, 2394 gil)' },
            { title = 'Fishing 10–20', note = '• Moat Carp (skill 11) in Misareaux Coast, Al Zahbi, West Ronfaure, on Ball of Insect Paste (Toji Mumosulah, Kazham, 42 gil)\n• Quus (skill 19) in Manaclipper, Bibiki Bay, Lufaise Meadows, on Lugworm (Solby-Maholby, Norg, 9 gil)\n• Yellow Globe (skill 17) in Open sea route to Al Zahbi, Open sea route to Mhaura, Batallia Downs, on Worm Lure (Babubu, Port Windurst, 540 gil)\n• Copper Frog (skill 16) in Oldton Movalpolos, North Gustaberg, Pashhow Marshlands, on Fly Lure (Babubu, Port Windurst, 540 gil)' },
            { title = 'Fishing 20–30', note = '• Tricolored Carp (skill 27) in Phanauet Channel, East Ronfaure, Jugner Forest, on Little Worm (Gelzerio, Bastok Mines, 4 gil)\n• Pipira (skill 29) in East Sarutabaruta, Yuhtunga Jungle, Yhoator Jungle, on Minnow (Cehn Teyohngo, Open sea route to Al Zahbi, 270 gil)\n• Tiger Cod (skill 29) in Batallia Downs, Beaucedine Glacier, Sauromugue Champaign, on Lugworm (Solby-Maholby, Norg, 9 gil)\n• Nebimonite (skill 27) in Sea Serpent Grotto, Ship bound for Selbina, Ship bound for Mhaura, on Ball of Crayfish Paste (Babubu, Port Windurst, 240 gil)' },
            { title = 'Fishing 30–40', note = '• Dark Bass (skill 33) in Phanauet Channel, Carpenters Landing, Lufaise Meadows, on Minnow (Cehn Teyohngo, Open sea route to Al Zahbi, 270 gil)\n• Giant Catfish (skill 31) in Phanauet Channel, Carpenters Landing, West Ronfaure, on Minnow (Cehn Teyohngo, Open sea route to Al Zahbi, 270 gil)\n• Shining Trout (skill 37) in Phanauet Channel, Carpenters Landing, East Ronfaure, on Minnow (Cehn Teyohngo, Open sea route to Al Zahbi, 270 gil)\n• Nosteau Herring (skill 39) in Batallia Downs, Beaucedine Glacier, Qufim Island, on Lugworm (Solby-Maholby, Norg, 9 gil)' },
